import 'dart:convert';
import 'dart:io';

import 'package:alula_app/workbench/tree_fuzzy_score.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('scores and ranges equal the actual pinned VS Code functions', () {
    // Generated by extracting filters.ts createMatches through _doScore and
    // strings.ts isEmojiImprecise from the pinned checkout, then executing
    // Node 24 stripTypeScriptTypes(mode: transform) output in an isolated VM.
    // No reference-repository imports, build scripts, or dependencies execute.
    final fixture = jsonDecode(
        File('test/fixtures/tree_fuzzy_score_vscode_4bda721.json')
            .readAsStringSync()) as Map<String, dynamic>;
    expect(fixture['commit'], '4bda7217fc83e8e838b1edd9ebaf21bb9b498c7e');
    expect(fixture['options'],
        {'firstMatchCanBeWeak': true, 'boostFullMatch': true});
    final cases = fixture['cases'] as List<dynamic>;
    expect(cases, hasLength(3482));
    for (var i = 0; i < cases.length; i++) {
      final entry = cases[i] as Map<String, dynamic>;
      final pattern = entry['pattern'] as String;
      final word = entry['word'] as String;
      final result = treeFuzzyScore(pattern, word);
      final expected = entry['expected'];
      final actual = result == null
          ? null
          : {
              'score': result.score,
              'matches': [
                for (final range in result.matches)
                  {'start': range.start, 'end': range.end},
              ],
            };
      expect(actual, expected,
          reason: 'fixture $i (${entry['category']}): '
              '${jsonEncode(pattern)} against ${jsonEncode(word)}');
    }
  });

  test('empty patterns and missing subsequences do not match', () {
    expect(treeFuzzyScore('', 'anything'), isNull);
    expect(treeFuzzyScore('a', ''), isNull);
    expect(treeFuzzyScore('abc', 'acb'), isNull);
    expect(treeFuzzyScore('long', 'lo'), isNull);
  });

  test('weak first matches remain valid and full matches receive their boost',
      () {
    final weak = treeFuzzyScore('a', 'ba')!;
    expect(weak.score, -10);
    expect(weak.matches, [(start: 1, end: 2)]);
    final full = treeFuzzyScore('ab', 'ab')!;
    expect(full.score, 12);
    expect(full.matches, [(start: 0, end: 2)]);
    expect(full.score, greaterThan(treeFuzzyScore('ab', 'abc')!.score - 5));
  });

  test('backtracking chooses the upstream alignment over a greedy subsequence',
      () {
    expect(treeFuzzyScore('abc', 'axbc_abc')!.matches,
        [(start: 0, end: 1), (start: 2, end: 4)]);
    expect(treeFuzzyScore('fb', 'fooBar')!.matches,
        [(start: 0, end: 1), (start: 3, end: 4)]);
  });

  test('UTF-16 ranges merge adjacent surrogate units and preserve offsets', () {
    expect(treeFuzzyScore('😀文', '😀中文.txt')!.matches,
        [(start: 0, end: 2), (start: 3, end: 4)]);
    expect(treeFuzzyScore('a\r\nb', '\uFEFFa\r\nb')!.matches,
        [(start: 1, end: 5)]);
    expect(treeFuzzyScore('\uDE00', '😀x')!.matches, [(start: 1, end: 2)]);
  });

  test('128-unit cap follows upstream including a split surrogate pair', () {
    expect(treeFuzzyScore('b', '${'a' * 128}b'), isNull);
    final full = treeFuzzyScore('a' * 129, 'a' * 160)!;
    expect(full.matches, [(start: 0, end: 128)]);
    final split = treeFuzzyScore('${'a' * 127}😀', '${'a' * 127}🚀')!;
    expect(split.matches, [(start: 0, end: 128)]);
  });

  test('results retain their ranges across later calls and are immutable', () {
    final first = treeFuzzyScore('fb', 'fooBar')!;
    treeFuzzyScore('a' * 128, 'a' * 128);
    treeFuzzyScore('nothing', 'no');
    expect(first.matches, [(start: 0, end: 1), (start: 3, end: 4)]);
    expect(() => first.matches.add((start: 2, end: 3)), throwsUnsupportedError);
  });
}
